def flatten(x):
    """Flatten arbitrarily nested lists and tuples into a single list, in order.

    Strings, bytes and dicts are treated as leaves and are never recursed into.
    """
    out = []
    for item in x:
        if isinstance(item, (list, tuple)):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out
